class Bowl<T> {
    private T thing;

    void put(T thing) {
        this.thing = thing;
    }

    T take() {
        return thing;
    }
}

public class Main {
    public static void main(String[] args) {
        Bowl<String> fish = new Bowl<>();
        fish.put("{word}");
        System.out.println("项链那只是 " + fish.take());

        Bowl<Integer> num = new Bowl<>();
        num.put({v});
        System.out.println("数字那只是 " + num.take() + "，加一是 " + (num.take() + 1));
    }
}
